/* eslint-disable no-console */
const fs = require("node:fs");
const path = require("node:path");
const { ts, extension, apiFiles, protocolProgram } = require("./contracts/program.js");
const prettier = require("prettier");
async function main() {
  const check = process.argv.includes("--check");
  const program = protocolProgram(check);
  const output = new Map();
  const wanted = new Set([
    ...apiFiles.map((file) => file.replace(/\.js$/, ".d.ts")),
    "shared/protocol-contracts.d.ts",
  ]);
  const header =
    "// Generated by npm run contracts:generate. Edit JS/JSDoc or protocol-contracts.ts.\n";
  program.emit(undefined, (file, text) => {
    const normalized = file.replaceAll(path.sep, "/");
    const relative = normalized.split("/.protocol-generated/apps/browser-extension/")[1];
    if (wanted.has(relative)) output.set(relative, header + text);
  });
  if (check) {
    const diagnostics = ts.getPreEmitDiagnostics(program);
    if (diagnostics.length) {
      console.error(
        ts.formatDiagnosticsWithColorAndContext(diagnostics, {
          getCurrentDirectory: () => process.cwd(),
          getCanonicalFileName: (file) => file,
          getNewLine: () => "\n",
        })
      );
      process.exitCode = 1;
    }
  }
  for (const relative of wanted) {
    const target = path.join(extension, relative);
    const emitted = output.get(relative);
    if (!emitted) throw new Error(`Declaration not emitted: ${relative}`);
    const content = await prettier.format(emitted, {
      ...(await prettier.resolveConfig(target)),
      filepath: target,
    });
    if (check) {
      if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== content) {
        console.error(`Stale declaration: ${relative}. Run npm run contracts:generate.`);
        process.exitCode = 1;
      }
    } else fs.writeFileSync(target, content);
  }
  console.log(
    check
      ? "Protocol checking completed; inspect exit status."
      : "Generated API declarations; type/runtime verification remains a separate Hermes gate."
  );
}
main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
